ALTER TABLE public.producers FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.product_change_requests (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL,
  producer_id uuid NOT NULL,
  requested_by uuid NOT NULL,
  proposed_payload jsonb NOT NULL,
  status text NOT NULL DEFAULT 'pending'::text,
  review_reason text,
  reviewed_by uuid,
  reviewed_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  CONSTRAINT product_change_requests_pkey PRIMARY KEY (id),
  CONSTRAINT product_change_requests_proposed_payload_check CHECK ((jsonb_typeof(proposed_payload) = 'object'::text)),
  CONSTRAINT product_change_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'withdrawn'::text])))
);
ALTER TABLE public.product_change_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.product_change_requests FORCE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS public.reviews (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL,
  product_id uuid NOT NULL,
  order_item_id uuid NOT NULL,
  rating smallint NOT NULL,
  title text,
  body text NOT NULL,
  media_paths text[] NOT NULL DEFAULT '{}'::text[],
  status text NOT NULL DEFAULT 'pending'::text,
  is_verified_purchase boolean NOT NULL DEFAULT true,
  merchant_reply text,
  merchant_replied_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  updated_at timestamp with time zone NOT NULL DEFAULT timezone('utc'::text, now()),
  moderated_by uuid,
  moderated_at timestamp with time zone,
  moderation_reason text,
  merchant_reply_by uuid,
  edited_at timestamp with time zone,
  CONSTRAINT reviews_order_item_id_key UNIQUE (order_item_id),
  CONSTRAINT reviews_pkey PRIMARY KEY (id),
  CONSTRAINT reviews_body_length_check CHECK (((char_length(body) >= 10) AND (char_length(body) <= 3000))),
  CONSTRAINT reviews_media_count_check CHECK ((COALESCE(array_length(media_paths, 1), 0) <= 5)),
  CONSTRAINT reviews_merchant_reply_length_check CHECK (((merchant_reply IS NULL) OR (char_length(merchant_reply) <= 2000))),
  CONSTRAINT reviews_moderation_reason_length_check CHECK (((moderation_reason IS NULL) OR (char_length(moderation_reason) <= 2000))),
  CONSTRAINT reviews_rating_check CHECK (((rating >= 1) AND (rating <= 5))),
  CONSTRAINT reviews_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'published'::text, 'rejected'::text, 'hidden'::text, 'withdrawn'::text]))),
  CONSTRAINT reviews_title_length_check CHECK (((title IS NULL) OR (char_length(title) <= 120)))
);
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews FORCE ROW LEVEL SECURITY;

